    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_orders CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_invoices CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_currencies CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_billing_profiles CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_posts CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_post_views CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_post_tags CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_post_tag_assignments CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_post_mentions CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_post_media CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_post_likes CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_post_groups CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_post_group_assignments CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_post_comments CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_email_orphaned_events CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_email_metrics CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_audit_logs CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_storage_dimensions CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_files CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_file_locations CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_file_instances CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_buckets CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_entity_data CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_entities CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_user_oauth_providers CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_email_templates CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_email_blocklist CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_email_logs CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_email_events CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_referral_codes CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_referral_code_usage CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_settings CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_users_tokens CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_users CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_user_roles CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit_user_role_assignments CASCADE")
    execute("DROP TABLE IF EXISTS #{p}phoenix_kit CASCADE")

    # Schema-scoped functions are dropped only for named-schema installs: a
    # public install's functions may be shared with other applications in the
    # database (never drop shared extensions / public functions).
    if prefix != "public" do
      execute("DROP FUNCTION IF EXISTS #{p}extract_primary_slug(slug_jsonb jsonb)")
      execute("DROP FUNCTION IF EXISTS #{p}uuid_generate_v7()")
    end
  end

  # V01 semantics: CREATE SCHEMA only when missing and requested — a bare
  # CREATE SCHEMA IF NOT EXISTS fails its privilege check for low-privilege
  # roles even when the schema exists. Immediate query: this module is the
  # first of any fresh run, so nothing is queued yet.
  defp ensure_schema!("public", _create_schema), do: :ok

  defp ensure_schema!(prefix, create_schema) do
    %{rows: [[exists]]} =
      repo().query!(
        "SELECT EXISTS (SELECT FROM information_schema.schemata WHERE schema_name = $1)",
        [prefix],
        log: false
      )

    cond do
      exists ->
        :ok

      create_schema ->
        # prefix is validated ([a-z_][a-z0-9_]*), safe unquoted
        repo().query!("CREATE SCHEMA " <> prefix, [], log: false)

      true ->
        raise "PhoenixKit baseline: schema " <>
                inspect(prefix) <>
                " does not exist and create_schema: false was given; " <>
                "create the schema or pass create_schema: true"
    end

    :ok
  end

  # Best-effort (v15/v31 lineage): the seeder modules are OPTIONAL — absent in
  # production releases and in installs without the emails module; failures
  # must never abort the baseline.
  defp seed_best_effort_helpers do
    for {mod, fun, args} <- [
          {Mix.Tasks.PhoenixKit.SeedTemplates, :run, [["--quiet"]]},
          {PhoenixKit.Modules.Emails.Templates, :seed_system_templates, []}
        ] do
      case Code.ensure_loaded(mod) do
        {:module, _} ->
          try do
            # credo:disable-for-next-line Credo.Check.Refactor.Apply
            apply(mod, fun, args)
          rescue
            error ->
              IO.puts("Warning: email-template seeding skipped: " <> inspect(error))
          end

        {:error, _} ->
          :ok
      end
    end

    :ok
  end
end
